# .intropy/local.yaml, pointing at the SFTP server the k3s setup scripts
# always install. Address and credentials are the fixture contract (see
# deploy-component/README.md) — dev values, not placeholders.
{{- range .topology.connectors }}
{{- $conn := . }}
{{- if eq (index $.local.bindings .name) "sftp" }}
---
apiVersion: dapr.io/v1alpha1
kind: Component
metadata:
  name: {{ .name }}
  labels:
    intropy.io/connector: {{ .name }}
spec:
  type: bindings.sftp
  version: v1
  metadata:
    - name: address
      value: sftp.fixtures.svc.cluster.local:22
    - name: username
      value: intropy
    - name: password
      value: intropy
scopes:
{{- range $conn.appIds }}
  - {{ . }}
{{- end }}
{{- end }}
{{- end }}

