func githubGet(t *testing.T, url string) []byte {
	t.Helper()
	req, _ := http.NewRequestWithContext(context.Background(), "GET", url, nil)
	req.Header.Set("Accept", "application/vnd.github+json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	data, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != 200 {
		t.Fatalf("%s: %s: %s", url, resp.Status, data)
	}
	return data
}

func TestRun(t *testing.T) {
	// Resolve the tarball URL for the tag exactly like FetchLibrary.
	meta := githubGet(t, "https://api.github.com/repos/integrio-intropy/intropy-templates/releases/tags/v0.2.1-beta.28")
	var rel struct {
		TagName string `json:"tag_name"`
	}
	json.Unmarshal(meta, &rel)
	t.Logf("tag: %s", rel.TagName)

	tb := githubGet(t, "https://api.github.com/repos/integrio-intropy/intropy-templates/tarball/" + rel.TagName)
	root := t.TempDir()
	gz, _ := gzip.NewReader(strings.NewReader(string(tb)))
	tr := tar.NewReader(gz)
	for {
		h, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatal(err)
		}
		if h.Typeflag != tar.TypeReg {
			continue
		}
		parts := strings.SplitN(h.Name, "/", 2)
		if len(parts) != 2 {
			continue
		}
		dest := filepath.Join(root, parts[1])
		os.MkdirAll(filepath.Dir(dest), 0o755)
		data, _ := io.ReadAll(tr)
		os.WriteFile(dest, data, 0o644)
	}

	// Simulate the CLI's localFileRules: every spec.files rule -> forced false.
	mdata, _ := os.ReadFile(filepath.Join(root, "deploy-component/template.yaml"))
	var manifest struct {
		Spec struct {
			Files []struct {
				Path string `yaml:"path"`
				When string `yaml:"when"`
			} `yaml:"files"`
		} `yaml:"spec"`
	}
	yaml.Unmarshal(mdata, &manifest)

	// Render deploy-component skeleton the way the CLI does for a local render.
	values := map[string]any{
		"name": "erp-loader", "system": "distribution", "appId": "erp-loader",
		"workload": "deployment", "registry": "dev", "kind": "loader",
		"env": "local",
		"gitops": map[string]any{"env": "local"},
		"topology": map[string]any{
			"connectors": []any{map[string]any{"name": "erp", "appIds": []any{"erp-loader"}}},
			"pubsubs":    []any{},
		},
		"local":    map[string]any{"bindings": map[string]any{"erp": "sftp"}},
		"scaffold": map[string]any{},
		"component": map[string]any{"name": "erp-loader"},
	}
	// spec.values
	values["imageRepo"] = "dev/integrations/erp-loader"
	values["imageTag"] = "unpinned"

	// Apply the narrowed file rules.
	excluded := map[string]bool{}
	for _, r := range manifest.Spec.Files {
		excluded[r.Path] = true
	}

	skel := filepath.Join(root, "deploy-component", "skeleton")
	out := t.TempDir()
	filepath.WalkDir(skel, func(p string, d os.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		rel, _ := filepath.Rel(skel, p)
		relSlash := filepath.ToSlash(rel)
		for pat := range excluded {
			// crude glob: exact or /** prefix
			if pat == relSlash || strings.HasSuffix(pat, "/**") && strings.HasPrefix(relSlash, strings.TrimSuffix(pat, "**")) {
				fmt.Printf("EXCLUDED by localFileRules: %s (rule %s)\n", relSlash, pat)
				return nil
			}
		}
		if strings.HasSuffix(relSlash, ".tmpl") {
			data, _ := os.ReadFile(p)
			tmpl, err := template.New(filepath.Base(relSlash)).Funcs(sprig.TxtFuncMap()).Option("missingkey=error").Parse(string(data))
			if err != nil {
				t.Errorf("parse %s: %v", relSlash, err)
				return nil
			}
			var buf strings.Builder
			// Render path segments too (overlays/{{ .env }}/...)
			relOut := strings.TrimSuffix(relSlash, ".tmpl")
			pt := template.Must(template.New("p").Funcs(sprig.TxtFuncMap()).Option("missingkey=error").Parse(relOut))
			var pb strings.Builder
			if err := pt.Execute(&pb, values); err != nil {
				t.Errorf("path %s: %v", relSlash, err)
				return nil
			}
			relOut = pb.String()
			if err := tmpl.Execute(&buf, values); err != nil {
				t.Errorf("exec %s: %v", relSlash, err)
				return nil
			}
			dest := filepath.Join(out, filepath.FromSlash(relOut))
			os.MkdirAll(filepath.Dir(dest), 0o755)
			os.WriteFile(dest, []byte(buf.String()), 0o644)
			if strings.HasPrefix(relOut, "overlays/local/") {
				fmt.Printf("--- %s ---\n%s\n", relOut, buf.String())
			}
		} else {
			data, _ := os.ReadFile(p)
			dest := filepath.Join(out, filepath.FromSlash(relSlash))
			os.MkdirAll(filepath.Dir(dest), 0o755)
			os.WriteFile(dest, data, 0o644)
		}
		return nil
	})
	// Now kustomize-build the overlay.
	cmd := exec.Command("kustomize", "build", filepath.Join(out, "overlays", "local"))
	built, err := cmd.CombinedOutput()
	t.Logf("kustomize: %v\n%s", err, built)
}
