func TestZZVerifySftpBinding(t *testing.T) {
	root := os.Getenv("INTROPY_TEMPLATES_DIR")
	if root == "" {
		t.Skip("set INTROPY_TEMPLATES_DIR")
	}
	f := newLocalFixtureWith(t, localTemplateEntries(t, root))
	writeLocalYAML(t, f.sourceDir, "connectors:\n  erp: sftp\n  price-master: http\n")

	var stdout, stderr bytes.Buffer
	opts := f.options(&stdout, &stderr)
	opts.Runner = nil
	if err := Local(context.Background(), opts); err != nil {
		t.Fatalf("Local: %v\nstderr: %s", err, stderr.String())
	}
	text := stdout.String()
	for _, want := range []string{
		"type: bindings.sftp",
		"sftp.fixtures.svc.cluster.local:22",
		"type: bindings.http",
		"http://http.fixtures.svc.cluster.local:8080",
	} {
		if !strings.Contains(text, want) {
			t.Errorf("missing %q in output", want)
		}
	}
	if strings.Contains(text, "REPLACE-ME") {
		t.Errorf("REPLACE-ME leaked into the local render")
	}
	if strings.Contains(text, "namespace: integrations") {
		t.Errorf("an overlay set its own namespace")
	}
	// Exactly one Component named erp.
	if n := strings.Count(text, "name: erp\n"); n != 1 {
		t.Errorf("Component erp rendered %d times, want 1", n)
	}
	apply := exec.Command("kubectl", "apply", "--dry-run=client", "-f", "-")
	apply.Stdin = &stdout
	if out, err := apply.CombinedOutput(); err != nil {
		t.Fatalf("kubectl dry-run: %v\n%s", err, out)
	}
	t.Logf("OK — output:\n%s", text)
}
